impl NumberId {
    /// Read the full-precision value from the committed registry.
    ///
    /// # Panics
    /// Panics only if generated offsets differ from the registry, which the fixed-point gate refuses.
    #[must_use]
    pub fn value(self) -> &'static str {
        let (start, end) = OFFSETS[self as usize];
        include_str!("pins_epoch.toml")
            .get(start..end)
            .expect("registry offsets must be regenerated")
    }

    /// Read an unsigned integer pin without a second literal.
    ///
    /// # Panics
    /// Panics only if the selected pin is not an unsigned machine integer, which a correctly typed consumer selection cannot arrange.
    #[must_use]
    pub fn integer(self) -> u64 {
        self.value().parse().expect("registry pin must be an unsigned integer")
    }
}
